import{_ as d,C as c,o as a,c as h,a2 as r,b as s,w as e,a as n,E as i,a3 as l}from"./chunks/framework.CZqXuAiL.js";const A=JSON.parse('{"title":"Protection Layers","description":"How Panel Firewall actually stops attacks — the L3/L4 ruleset and presets, SMART EWMA auto-mitigation, and the L7 access-log HTTP-flood sensor.","frontmatter":{"title":"Protection Layers","description":"How Panel Firewall actually stops attacks — the L3/L4 ruleset and presets, SMART EWMA auto-mitigation, and the L7 access-log HTTP-flood sensor."},"headers":[],"relativePath":"panel-firewall/architecture/protection-layers.md","filePath":"panel-firewall/architecture/protection-layers.md","lastUpdated":1785522036000}'),p={name:"panel-firewall/architecture/protection-layers.md"};function u(m,t,g,b,f,y){const o=c("Mermaid");return a(),h("div",null,[t[2]||(t[2]=r('<h1 id="protection-layers" tabindex="-1">Protection Layers <a class="header-anchor" href="#protection-layers" aria-label="Permalink to &quot;Protection Layers&quot;">​</a></h1><p>Panel Firewall stacks three independent layers in the kernel&#39;s <code>PTDL_*</code> chains, hooked into INPUT for the panel&#39;s HTTP/HTTPS ports. Rule order is deliberate — cheap accepts and known-bad drops happen before any rate accounting.</p><hr><h2 id="layer-1-—-static-l3-l4-ruleset" tabindex="-1">Layer 1 — Static L3/L4 ruleset <a class="header-anchor" href="#layer-1-—-static-l3-l4-ruleset" aria-label="Permalink to &quot;Layer 1 — Static L3/L4 ruleset&quot;">​</a></h2><p>Built by <code>RuleEngine</code> as a pure config → desired-state transform, applied atomically. Evaluation order:</p><ol><li><strong>Loopback</strong> → ACCEPT</li><li><strong>Whitelist ipset</strong> (<code>ptdl-wl-admin</code>) → ACCEPT — <em>before everything else</em>, so whitelisted IPs can never be locked out</li><li><strong>Established/related</strong> → ACCEPT (fast path; existing connections skip all checks)</li><li><strong>Permanent blacklist ipset</strong> → DROP</li><li><strong>Temp-ban ipset</strong> (<code>ptdl-bl-temp</code>) → DROP</li><li><strong>Packet hygiene</strong> → DROP: conntrack INVALID, fragments, TCP flags ALL NONE (null scan), SYN+FIN, FIN/URG/PSH (XMAS), non-SYN packets in NEW state</li><li><strong>Per-IP NEW-connection hashlimit</strong> → DROP above preset CPS (bursts allowed)</li><li><strong>Per-IP SYN hashlimit</strong> → DROP above preset SYN/s</li><li><strong>RETURN</strong> — <em>never</em> a final DROP: unmatched traffic falls back to your normal INPUT chain, so the addon can&#39;t lock out SSH or break a DROP-by-default policy</li></ol><h3 id="presets" tabindex="-1">Presets <a class="header-anchor" href="#presets" aria-label="Permalink to &quot;Presets&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Preset</th><th>PPS/IP</th><th>New conn/s</th><th>SYN/s</th><th>Burst</th><th>Concurrent</th><th>Use when</th></tr></thead><tbody><tr><td><code>low</code></td><td>200</td><td>20</td><td>30</td><td>60</td><td>100</td><td>Small private panels</td></tr><tr><td><code>medium</code> <em>(default)</em></td><td>500</td><td>40</td><td>60</td><td>120</td><td>200</td><td>Typical production panel</td></tr><tr><td><code>high</code></td><td>1500</td><td>80</td><td>120</td><td>240</td><td>500</td><td>Busy public panel</td></tr><tr><td><code>veryHigh</code></td><td>4000</td><td>150</td><td>250</td><td>500</td><td>1500</td><td>Heavy API/websocket usage</td></tr><tr><td><code>underAttack</code></td><td>100</td><td>10</td><td>15</td><td>30</td><td>50</td><td>Active attack — tight until it passes</td></tr></tbody></table><hr><h2 id="layer-2-—-smart-adaptive-mitigation" tabindex="-1">Layer 2 — SMART adaptive mitigation <a class="header-anchor" href="#layer-2-—-smart-adaptive-mitigation" aria-label="Permalink to &quot;Layer 2 — SMART adaptive mitigation&quot;">​</a></h2><p>The SMART monitor samples host counters every 5 seconds and decides <em>for itself</em> when traffic is abnormal — no static threshold fits every panel.</p>',11)),(a(),s(l,null,{default:e(()=>[i(o,{id:"mermaid-214",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5B%2Fproc%20conntrack%20count%3Cbr%2F%3Eevery%205s%2F%5D%20--%3E%20B%5BMetricCollector%3Cbr%2F%3Ecps_in%2C%20pps_in%2C%20syn_per_sec%2C%20conntrack_pct%5D%0A%20%20%20%20B%20--%3E%20C%5BEWMADetector%3Cbr%2F%3E%CE%B1%200.1%2C%20%CE%B2%200.05%5D%0A%20%20%20%20C%20--%3E%7Cvalue%20within%204%CF%83%20of%20baseline%7C%20D%5Bnothing%5D%0A%20%20%20%20C%20--%3E%7Canomaly%7C%20E%5Bconfidence%20score%5D%0A%20%20%20%20E%20--%3E%7C%3E%200.55%7C%20F%5BL2%3A%205%20new%20conn%2Fs%20per%20IP%5D%0A%20%20%20%20E%20--%3E%7C%3E%200.85%7C%20G%5BL3%3A%20drop%20ALL%20new%20connections%5D%0A%20%20%20%20E%20--%3E%7Cdefault%7C%20H%5BL1%3A%20hashlimit%20NEW%20per%20IP%20at%20pps%2F4%5D%0A%20%20%20%20F%20--%3E%20I%5Bcooldown%20120s%5D%0A%20%20%20%20G%20--%3E%20J%5Bcooldown%20300s%5D%0A%20%20%20%20H%20--%3E%20K%5Bcooldown%2030s%5D%0A%20%20%20%20I%20--%3E%20L%7Bstill%20anomalous%3F%7D%0A%20%20%20%20J%20--%3E%20L%0A%20%20%20%20K%20--%3E%20L%0A%20%20%20%20L%20--%3E%7Cno%7C%20M%5Bauto-clear%5D%0A"})]),fallback:e(()=>[...t[0]||(t[0]=[n(" Loading... ",-1)])]),_:1})),t[3]||(t[3]=r('<p>Key properties:</p><ul><li><strong>EWMA + variance baseline</strong> (α 0.1 for the mean, β 0.05 for variance) with a warmup period — the detector learns what &quot;normal&quot; looks like on <em>your</em> host instead of using a hardcoded rate</li><li><strong>Anomaly = 4σ above baseline</strong> (tunable); confidence picks the mitigation level</li><li><strong>L1 → L2 → L3</strong> escalate from &quot;slow the flood&quot; to &quot;drop all new connections&quot; (established sessions always survive)</li><li><strong>Cooldowns auto-clear</strong> (30s/120s/300s): mitigation turns itself off when traffic normalizes — nobody has to remember</li><li>Every detection and level change is audited, graphed in analytics, and can fire a webhook</li></ul><h2 id="layer-3-—-l7-http-flood-sensor" tabindex="-1">Layer 3 — L7 HTTP-flood sensor <a class="header-anchor" href="#layer-3-—-l7-http-flood-sensor" aria-label="Permalink to &quot;Layer 3 — L7 HTTP-flood sensor&quot;">​</a></h2><p>L3/L4 rate limits can&#39;t see the difference between 50 requests and 50 <em>expensive</em> requests. The L7 sensor reads the one place that knows: the web server&#39;s access log.</p>',4)),(a(),s(l,null,{default:e(()=>[i(o,{id:"mermaid-251",class:"mermaid",graph:"graph%20LR%0A%20%20%20%20LOG%5Bnginx%2Fapache%2Fcaddy%3Cbr%2F%3Eaccess.log%5D%20--%3E%20W%5BAccessLogWatcher%3Cbr%2F%3Efd%20tail%2C%20offset%20tracking%2C%3Cbr%2F%3Erotation-aware%5D%0A%20%20%20%20W%20--%3E%20M%5BL7Monitor%3Cbr%2F%3Eper-IP%20sliding%20window%5D%0A%20%20%20%20M%20--%3E%7Ccount%20%3E%20rpm%20%C3%97%20window%2F60%7C%20G%7Bguards%7D%0A%20%20%20%20G%20--%3E%7Cprivate%2Freserved%7C%20X%5Bskip%5D%0A%20%20%20%20G%20--%3E%7Cwhitelisted%7C%20X%0A%20%20%20%20G%20--%3E%7Cvalid%20public%20IP%7C%20B%5BBanManager%3Cbr%2F%3Etemp%20ban%2015m%5D%0A%20%20%20%20B%20--%3E%20S%5Bptdl-bl-temp%20ipset%20%E2%86%92%20DROP%5D%0A"})]),fallback:e(()=>[...t[1]||(t[1]=[n(" Loading... ",-1)])]),_:1})),t[4]||(t[4]=r('<ul><li><strong>Zero web-server changes</strong> — reads the existing combined-format log; autodetects nginx/apache/httpd/caddy paths</li><li><strong>Rotation-safe</strong> — follows by fd with byte-offset tracking; logrotate rename/truncate is detected and re-followed without losing lines; first open starts at EOF (never retro-bans history)</li><li><strong>Fail-open</strong> — missing/unreadable log means no L7 bans, never a crash; retried every poll</li><li><strong>Abuse-proof</strong> — private/reserved IPs and whitelist entries are never banned; ban actions are budgeted (<code>maxBansPerMinute</code>, default 20) so a log flood can&#39;t churn the ipset; re-offenses while banned are deduplicated</li><li><strong>Observable</strong> — <code>l7_requests_per_min</code>, tracked IPs, ban totals feed the analytics page; recent bans (with rate evidence) appear in the SMART status and dashboard card</li></ul><hr><h2 id="layer-interaction" tabindex="-1">Layer interaction <a class="header-anchor" href="#layer-interaction" aria-label="Permalink to &quot;Layer interaction&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Attack</th><th>Stopped by</th></tr></thead><tbody><tr><td>SYN flood</td><td>Layer 1 SYN hashlimit; SMART L2/L3 if distributed</td></tr><tr><td>Connection exhaustion</td><td>Layer 1 CPS hashlimit + conntrack_pct metric in SMART</td></tr><tr><td>Null/XMAS/fragment scans</td><td>Layer 1 hygiene rules</td></tr><tr><td>Single-IP HTTP flood</td><td>Layer 1 CPS limit first, L7 temp ban as the signal-rich backstop</td></tr><tr><td>Distributed HTTP flood (botnet)</td><td>SMART EWMA → L1/L2/L3 global throttles</td></tr><tr><td>Slow churn under all rate limits</td><td><strong>Not covered</strong> — see below</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Honest limitation</p><p>A slow, widely-distributed L7 attack that stays under every per-IP rate (thousands of IPs × a few requests/minute each) passes all three layers — that&#39;s what upstream WAFs/CDNs (or the sibling XDP projects) are for. Panel Firewall&#39;s job is to keep the panel host alive and responsive against the common floods, and to never lock you out while doing it.</p></div>',5))])}const C=d(p,[["render",u]]);export{A as __pageData,C as default};
